('dam-dau-nanh-kho', 'Đạm đậu nành khô (TVP, sườn non chay khô)', 'Textured soy protein (TVP), dry', array['sườn non chay khô','thịt chay khô','tvp','textured vegetable protein']::text[], array['vegetarian','chay','protein','processed','dry']::text[], 'vegetarian', 'protein', 311, 41.7, 34.7, 3, 17.5, 25, 'g', 'processed', 'dry', 1, 'USDA FoodData Central – SR Legacy (SR28), NDB 16106 "Meat extender", giá trị/100 g. USDA ghi tên "Meat extender" (đạm đậu nành dạng sợi/miếng, khô). Sản phẩm Việt Nam khác nhau, xem nhãn bao bì.', 'VERIFIED', null),
('cha-lua-chay', 'Chả lụa chay', 'Vegetarian sausage loaf (cha lua chay)', array['giò chay','chả chay','vegetarian ham']::text[], array['vegetarian','chay','protein','processed','prepared']::text[], 'vegetarian', 'protein', 189, 17.8, 4.4, 11.1, 1.1, 50, 'g', 'processed', 'prepared', 1, 'ƯỚC TÍNH – USDA FoodData Central – SR Legacy (SR28), NDB 43131 "Luncheon slices, meatless", giá trị/100 g. Không có bản ghi chả lụa chay. Dùng USDA 43131 "Luncheon slices, meatless" (chả lát chay) làm giá trị gần nhất. Chả chay Việt Nam thường nhiều tinh bột và ít đạm hơn: luôn ưu tiên nhãn bao bì.', 'ESTIMATED', null),
('mi-can', 'Mì căn (seitan) luộc', 'Seitan (wheat gluten), simmered', array['mì căn','mì cân','seitan','wheat meat']::text[], array['vegetarian','chay','protein','boiled','cooked']::text[], 'vegetarian', 'protein', 122, 24.8, 4.6, 0.6, 0.2, 100, 'g', 'boiled', 'cooked', 1, 'ƯỚC TÍNH – tính từ công thức 1 phần 100 g: bột gluten lúa mì 33 g (USDA 48052) + nước 67 g (0 kcal). Tổng 1 phần: 122 kcal, 24.8 g đạm. Số liệu nguyên liệu: USDA FoodData Central – SR Legacy (SR28), theo mã NDB. Giả định mì căn chín gồm 1 phần bột gluten và 2 phần nước theo khối lượng; mì căn càng khô thì đạm/100 g càng cao. Thực tế thay đổi theo quán, khẩu phần và lượng dầu.', 'ESTIMATED', null),
('suon-non-chay-chien', 'Sườn non chay chiên', 'Fried vegetarian "ribs" (soy protein)', array['sườn chay','sườn non chay','soy ribs']::text[], array['vegetarian','chay','protein','fried','cooked']::text[], 'vegetarian', 'protein', 164, 12.8, 10.7, 8.6, 5.4, 65, 'g', 'fried', 'cooked', 1, 'ƯỚC TÍNH – tính từ công thức 1 phần (2–3 miếng) 65 g: đạm đậu nành khô (TVP) 20 g (USDA 16106) + nước 40 g (0 kcal) + dầu ăn 5 g (USDA 04044). Tổng 1 phần (2–3 miếng): 106 kcal, 8.3 g đạm. Số liệu nguyên liệu: USDA FoodData Central – SR Legacy (SR28), theo mã NDB. 20 g sườn chay khô ngâm nở gấp 3 lần, chiên thấm khoảng 5 g dầu. Thực tế thay đổi theo quán, khẩu phần và lượng dầu.', 'ESTIMATED', null),
('com-tam-chay', 'Cơm tấm chay (sườn non chay)', 'Vegetarian broken rice with soy "ribs"', array['cơm tấm chay','cơm sườn chay']::text[], array['vegetarian','chay','rice_dish','prepared','prepared']::text[], 'vegetarian', 'rice_dish', 123, 4.1, 21, 2.5, 1.4, 368, 'g', 'prepared', 'prepared', 1, 'ƯỚC TÍNH – tính từ công thức 1 đĩa 368 g: cơm trắng 200 g (USDA 20045) + đạm đậu nành khô (TVP) 20 g (USDA 16106) + nước 55 g (0 kcal) + dầu ăn 8 g (USDA 04044) + hành lá 5 g (USDA 11291) + dưa leo 30 g (USDA 11205) + cà rốt 15 g (USDA 11124) + củ cải trắng 15 g (USDA 11430) + nước tương 10 g (USDA 16123) + đường 10 g (USDA 19335). Tổng 1 đĩa: 452 kcal, 15.1 g đạm. Số liệu nguyên liệu: USDA FoodData Central – SR Legacy (SR28), theo mã NDB. Gồm 200 g cơm, 2–3 miếng sườn chay (20 g khô), mỡ hành, đồ chua, dưa leo, nước tương pha đường. Không tính bì chay, chả chay (thêm riêng nếu có). Thực tế thay đổi theo quán, khẩu phần và lượng dầu.', 'ESTIMATED', null),
('pho-chay', 'Phở chay', 'Vegetarian pho', array['phở chay','phở nấm','phở đậu hũ']::text[], array['vegetarian','chay','noodle_soup','prepared','prepared']::text[], 'vegetarian', 'noodle_soup', 54, 2.2, 8.6, 1.4, 1, 771, 'g', 'prepared', 'prepared', 1, 'ƯỚC TÍNH – tính từ công thức 1 tô 771 g: bún/bánh phở chín 200 g (USDA 20134) + đậu hũ chiên 50 g (USDA 16429) + nấm đông cô 30 g (USDA 11238) + nấm bào ngư 30 g (USDA 11987) + giá 30 g (USDA 11043) + hành tây 15 g (USDA 11282) + hành lá 5 g (USDA 11291) + rau thơm 3 g (USDA 11165) + cà rốt 20 g (USDA 11124) + củ cải trắng 30 g (USDA 11430) + nước tương 5 g (USDA 16123) + đường 3 g (USDA 19335) + nước 350 g (0 kcal). Tổng 1 tô: 416 kcal, 16.7 g đạm. Số liệu nguyên liệu: USDA FoodData Central – SR Legacy (SR28), theo mã NDB. Nước dùng rau củ không dầu. Quán cho nhiều đậu hũ hơn thì đạm tăng (mỗi 50 g đậu hũ chiên thêm ~9 g đạm, 135 kcal). Thực tế thay đổi theo quán, khẩu phần và lượng dầu.', 'ESTIMATED', null),
('bun-rieu-chay', 'Bún riêu chay', 'Vegetarian tomato noodle soup (bun rieu chay)', array['bún riêu chay']::text[], array['vegetarian','chay','noodle_soup','prepared','prepared']::text[], 'vegetarian', 'noodle_soup', 60, 2.6, 7.8, 2.3, 0.8, 803, 'g', 'prepared', 'prepared', 1, 'ƯỚC TÍNH – tính từ công thức 1 tô 803 g: bún/bánh phở chín 200 g (USDA 20134) + đậu hũ trắng 60 g (USDA 16427) + đậu hũ chiên 50 g (USDA 16429) + cà chua 80 g (USDA 11529) + nấm rơm 30 g (USDA 11989) + dầu ăn 5 g (USDA 04044) + giá 20 g (USDA 11043) + nước tương 5 g (USDA 16123) + đường 3 g (USDA 19335) + nước 350 g (0 kcal). Tổng 1 tô: 485 kcal, 20.7 g đạm. Số liệu nguyên liệu: USDA FoodData Central – SR Legacy (SR28), theo mã NDB. Riêu làm từ đậu hũ trắng tán, thêm đậu hũ chiên, cà chua xào dầu, nấm rơm. Thực tế thay đổi theo quán, khẩu phần và lượng dầu.', 'ESTIMATED', null),
('banh-mi-chay', 'Bánh mì chay (chả lụa chay, pate nấm)', 'Vegetarian banh mi', array['bánh mì chay']::text[], array['vegetarian','chay','bread','prepared','prepared']::text[], 'vegetarian', 'bread', 183, 8.9, 23.2, 6.3, 1.7, 180, 'g', 'prepared', 'prepared', 1, 'ƯỚC TÍNH – tính từ công thức 1 ổ 180 g: bánh mì 70 g (USDA 18029) + chả lụa chay (tính như chả chay đóng gói) 40 g (USDA 43131) + nấm bào ngư 20 g (USDA 11987) + dầu ăn 5 g (USDA 04044) + cà rốt 10 g (USDA 11124) + củ cải trắng 10 g (USDA 11430) + dưa leo 15 g (USDA 11205) + rau thơm 3 g (USDA 11165) + nước tương 5 g (USDA 16123) + ớt 2 g (USDA 11819). Tổng 1 ổ: 329 kcal, 16.1 g đạm. Số liệu nguyên liệu: USDA FoodData Central – SR Legacy (SR28), theo mã NDB. Pate nấm tính là 20 g nấm xay + 5 g dầu. Chả lụa chay tính theo chả chay đóng gói của USDA (xem món Chả lụa chay). Thực tế thay đổi theo quán, khẩu phần và lượng dầu.', 'ESTIMATED', null),
('mi-xao-chay', 'Mì xào chay rau củ', 'Vegetarian stir-fried noodles with vegetables', array['mì xào chay','mì xào rau củ']::text[], array['vegetarian','chay','noodle_dry','stir_fried','prepared']::text[], 'vegetarian', 'noodle_dry', 146, 5.8, 19.6, 5.3, 2.2, 383, 'g', 'stir_fried', 'prepared', 1, 'ƯỚC TÍNH – tính từ công thức 1 đĩa 383 g: mì sợi lúa mì chín (không trứng) 200 g (USDA 20121) + đậu hũ chiên 40 g (USDA 16429) + bắp cải 50 g (USDA 11109) + cà rốt 30 g (USDA 11124) + nấm bào ngư 40 g (USDA 11987) + tỏi 3 g (USDA 11215) + dầu ăn 10 g (USDA 04044) + nước tương 10 g (USDA 16123). Tổng 1 đĩa: 560 kcal, 22.4 g đạm. Số liệu nguyên liệu: USDA FoodData Central – SR Legacy (SR28), theo mã NDB. Dùng mì sợi lúa mì không trứng. Mì trứng không phải món thuần chay. Thực tế thay đổi theo quán, khẩu phần và lượng dầu.', 'ESTIMATED', null),
